def compute_dominators(cfg):
    all_b = set(cfg.blocks)
    dom = {b: set(all_b) for b in all_b}
    dom[cfg.entry] = {cfg.entry}
    changed = True
    while changed:
        changed = False
        for b in all_b:
            if b == cfg.entry: continue
            preds = [p for p in cfg.blocks[b].preds if p in cfg.blocks]
            new = ({b} if not preds
                   else set.intersection(*(dom[p] for p in preds)) | {b})
            if new != dom[b]:
                dom[b] = new; changed = True
    return dom

def dominates_bruteforce(cfg, d, b):          # independent checker
    if d == b or d == cfg.entry: return True
    seen, q = {cfg.entry}, deque([cfg.entry])
    while q:
        x = q.popleft()
        for y in cfg.blocks[x].succs:
            if y == d or y in seen: continue
            if y == b: return False
            seen.add(y); q.append(y)
    return True

def split_edge(cfg, src, dst):
    Sblk = cfg.add_block(); S = Sblk.bid; Sblk.split_of = (src, dst)
    cfg.edges.discard((src, dst, NORMAL))
    cfg.add_edge(src, S, NORMAL); cfg.add_edge(S, dst, NORMAL)
    if not cfg.has_any_edge(src, dst):        # keep parallel exception edge
        cfg.blocks[dst].preds.remove(src); cfg.blocks[src].succs.remove(dst)
    for phi in cfg.blocks[dst].phis:          # move operands to the new pred
        if src in phi.inputs: phi.inputs[S] = phi.inputs.pop(src)
    return S
